package com.smartspend.util;
import javafx.geometry.Insets;import javafx.scene.Node;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.scene.paint.Color;import javafx.scene.text.Font;import javafx.stage.Window;
public final class UI {private UI(){} public static Label title(String s){Label l=new Label(s);l.getStyleClass().add("page-title");return l;}public static Label subtitle(String s){Label l=new Label(s);l.getStyleClass().add("muted");return l;}public static VBox card(Node... n){VBox v=new VBox(10,n);v.getStyleClass().add("card");return v;}public static Button button(String s){Button b=new Button(s);b.getStyleClass().add("primary-button");return b;}public static Button ghost(String s){Button b=new Button(s);b.getStyleClass().add("ghost-button");return b;}public static TextField input(String prompt){TextField t=new TextField();t.setPromptText(prompt);t.getStyleClass().add("input-field");return t;}public static PasswordField password(String prompt){PasswordField p=new PasswordField();p.setPromptText(prompt);p.getStyleClass().add("input-field");return p;}public static void alert(Window w,String title,String msg){Alert a=new Alert(Alert.AlertType.INFORMATION);a.initOwner(w);a.setTitle(title);a.setHeaderText(null);a.setContentText(msg);a.showAndWait();}public static void error(Window w,String msg){Alert a=new Alert(Alert.AlertType.ERROR);a.initOwner(w);a.setTitle("SmartSpend");a.setHeaderText(null);a.setContentText(msg);a.showAndWait();}public static String money(double x){return "₹"+String.format("%,.2f",x);} }
